});

let zaehlerWert = 0;
let knopf = document.querySelector('#knopf');
knopf.addEventListener('click', () => {
  zaehlerWert++;
  if (zaehlerWert >= 3) {
    document.querySelector('#anzeige').textContent = 'Geschafft!';
  } else {
    document.querySelector('#anzeige').textContent = zaehlerWert;
  }
});

